COMMIT;
SELECT l.siglas,l.id,(SELECT count(*) FROM public.articulos a WHERE a.ley_id=l.id) AS fragmentos,(SELECT count(*) FROM public.temas t WHERE t.ley_id=l.id) AS temas,l.fecha_publicacion FROM public.leyes l WHERE l.id='7b6d37f8-5fd5-485e-bc5d-640a9b234950';
